var frontierSnapshot = {"generatedAt":"2026-10-12T16:43:55.229Z","cadence":"Every Monday at 07:17 UTC","windowDays":45,"method":"Automated topic matching followed by newest-first ordering. This is a discovery feed, not an impact or efficacy ranking.","sources":[{"id":"europe-pmc","name":"Europe PMC","kind":"paper","url":"https://europepmc.org/RestfulWebService","note":"Newest peer-reviewed and indexed literature matching the atlas topic vocabulary."},{"id":"preprints","name":"Europe PMC preprint index","kind":"preprint","url":"https://europepmc.org/RestfulWebService","note":"Recent preprints indexed from source servers; each item links to its original record and is marked as not yet peer reviewed."},{"id":"clinicaltrials","name":"ClinicalTrials.gov","kind":"trial","url":"https://clinicaltrials.gov/data-api/api","note":"Recently updated registrations, not evidence that a treatment is effective."},{"id":"nibib","name":"NIH NIBIB News","kind":"news","url":"https://www.nibib.nih.gov/rss","note":"Current official biomedical-engineering news feed; item dates are shown as the weekly observation date when the feed omits them."}],"errors":[],"items":[{"id":"preprint-10.64898/2026.10.08.26365079","kind":"preprint","title":"Static and dynamic noise abolish altruistic biases in Parkinson's disease independent of deep brain stimulation","date":"2026-10-11","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.08.26365079","summary":"There are known alterations in decision-making attributed to Parkinson's disease. Yet little is known about how those alterations affect decisions in social contexts. We aimed to assess social decision-making in healthy human volunteers as well as people with Parkinson's disease treated with deep brain stimulation of the subthalamic nucleus. Twenty healthy controls and twenty-two people with Parkinson's in both the stimulation ON and OFF conditions took part in a social discounting task that measured the degree of generosity toward others as a function of social-emotional distance. Using a computational approach…","authors":"Hubschmid F, Sellitto M, Bahners BH, Pirenne T, Kalenscher T, schnitzler A, van Wingerden M, Florin E.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"trial-nct07866950","kind":"trial","title":"Transcranial Direct Current Stimulation in High-level Volleyball Players During Fatigue","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07866950","summary":"The goal of this clinical trial is to learn if tDCS works to treat fatigue state in athletes. The main questions it aims to answer are: Does tDCS on the physical performance in high-level volleyball players during dual fatigue. What montages have the best effects on fatigue state. Researchers will compare tDCS to a placebo (sham stimulation) to see if tDCS have the effects on fatigue state in athletes. Participants will: Received four 10 min sessions tDCS in counterbalanced order.","authors":"Beijing Sport University","venue":"NCT07866950 · NA","status":"completed","topics":["stimulate"]},{"id":"trial-nct06577454","kind":"trial","title":"Measuring the Effects of Neurostimulation on Risky and Ambiguous Decision-Making Capacity in People With and Without Substance Use Disorder","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT06577454","summary":"Background: The purpose of this study is to understand how a type of brain stimulation, transcranial magnetic stimulation (TMS), may help those who use opioids such as heroin or methadone. TMS uses brief magnetic pulses to affect brain activity, and is approved by the FDA to treat some mental health problems and substance use. We will evaluate how TMS may help make it easier to make certain kinds of decisions that could help one manage their opioid use. Our findings may provide support for the use of brain stimulation as a treatment to reduce opioid use. Objective: To understand how TMS affects brain activity as…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT06577454 · NA","status":"suspended","topics":["record","stimulate"]},{"id":"trial-nct05143554","kind":"trial","title":"Auricular Neurostimulation for Chemotherapy Induced Nausea and Vomiting","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT05143554","summary":"This study evaluates the efficacy of auricular percutaneous electrical nerve field stimulator in children, adolescents and young adults with chemotherapy induced nausea and vomiting.","authors":"Medical College of Wisconsin","venue":"NCT05143554 · NA","status":"completed","topics":["record"]},{"id":"trial-nct07868614","kind":"trial","title":"Intraoperative Microelectrode Recordings Using MAVEN Compared to Standard Recording Apparatuses","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07868614","summary":"The purpose of this research is to determine if the electrophysiologic data collected from standard-of-care microelectrode recordings during human deep brain stimulation (DBS) surgery will be the same using the MAVEN device compared with the standard Alpha Omega device with either a tungsten standard-of-care microelectrode (for microelectrode recordings), or a carbon-fiber microelectrode (for neurotransmitter recordings). The number of microelectrodes used for both the tungsten and the carbon-fiber version will be the same as the standard-of-care.","authors":"Mayo Clinic","venue":"NCT07868614","status":"recruiting","topics":["record","stimulate"]},{"id":"trial-nct07780032","kind":"trial","title":"Neuromodulation to Overcome Severe Restless Legs Syndrome","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07780032","summary":"This prospective, single-center, first-in-indication feasibility study will evaluate the safety and preliminary effectiveness of spinal cord stimulation (SCS) for the treatment of severe, treatment-refractory primary Restless Legs Syndrome (RLS). Participants will undergo implantation of the Saluda Medical Evoke® Spinal Cord Stimulation System and will be followed for 24 months with clinical, neurophysiological, and patient-reported outcome assessments.","authors":"Marshall Holland","venue":"NCT07780032 · NA","status":"not yet recruiting","topics":["stimulate","restore"]},{"id":"trial-nct01550575","kind":"trial","title":"Patient Retrospective Outcomes (PRO)","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT01550575","summary":"This study will evaluate de-identified (anonymous) data in subject medical charts to review the clinical outcomes of various treatment approaches in the treatment of chronic pain.","authors":"Boston Scientific Corporation","venue":"NCT01550575","status":"recruiting","topics":["record"]},{"id":"trial-nct07868055","kind":"trial","title":"Self-administered Neurostimulation Intervention for Firefighter Traumatic Stress to Reduce Alcohol Use: Pilot Study","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07868055","summary":"The goal of this clinical trial is to evaluate the feasibility, acceptability, and appropriateness of a transcutaneous auricular neurostimulation (tAN) protocol in firefighters who engage in heavy drinking, have at least a mild alcohol use disorder, and report above-average posttraumatic stress symptoms (PTS). The main questions it aims to answer are: * How feasible do firefighter participants rate the study procedures on the Feasibility of Intervention Measure? * How do firefighter participants rate the acceptability of the study procedures (Acceptability of Intervention Measure) and the appropriateness of the…","authors":"University of Cincinnati","venue":"NCT07868055 · NA","status":"not yet recruiting","topics":["stimulate"]},{"id":"trial-nct04618471","kind":"trial","title":"Paresthesia-Free Fast-Acting Subperception (FAST) Study","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04618471","summary":"Study to evaluate the effectiveness of FAST-SCS (fast-acting paresthesia-free therapy) and additional SCS therapy options in patients with chronic pain using Boston Scientific WaveWriter SCS Systems.","authors":"Boston Scientific Corporation","venue":"NCT04618471 · NA","status":"active not recruiting","topics":["record"]},{"id":"trial-nct07521930","kind":"trial","title":"Interfacing With NeuroTechnology to Expand Neural Throughput (INTENT)","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07521930","summary":"The goal of this clinical trial is to evaluate the safety and preliminary efficacy of an implantable device that records and stimulates different areas of the brain to allow adults affected by disabling paralysis (see Eligibility for more details) to control and receive feedback from assistive devices.","authors":"Johns Hopkins University","venue":"NCT07521930 · NA","status":"recruiting","topics":["restore"]},{"id":"trial-nct04543773","kind":"trial","title":"Individualized Targeting and Neuromodulation of Late-Life Depression","date":"2026-10-09","observedAt":"2026-10-12","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04543773","summary":"An open-label, single-arm, clinical research study about how to make transcranial magnetic stimulation (TMS), an FDA-approved treatment, more effective for patients with late-life depression using fMRI.","authors":"University of New Mexico","venue":"NCT04543773 · NA","status":"active not recruiting","topics":["record","stimulate"]},{"id":"paper-pmc-pmc13643595","kind":"paper","title":"Neuromodulation for post-stroke aphasia rehabilitation: established cortical stimulation and emerging network-based targets","date":"2026-10-08","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13643595","summary":"Europe PMC does not provide an abstract for this record.","authors":"De Luca M, Federico G, Rigatti D, Gigliotta O, Marangolo P.","venue":"Frontiers in human neuroscience","status":"Peer-reviewed / indexed","topics":["stimulate","restore"]},{"id":"paper-pmc-pmc13647036","kind":"paper","title":"Continuous Subcutaneous Apomorphine as a Temporary Bridging Therapy for Dopamine Dysregulation Syndrome in Patients with Deep Brain Stimulation","date":"2026-10-08","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13647036","summary":"Europe PMC does not provide an abstract for this record.","authors":"Binder T, Hartig J, Sitzmann L, Ip C, Capetian P, Lange F, Reich M, Daniels C, Volkmann J.","venue":"Movement disorders clinical practice","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.20944/preprints202610.0520.v1","kind":"preprint","title":"The Gut–Liver–Brain Axis in Neurodegeneration: Unraveling Metabolic–Immune Crosstalk from Peripheral Sensing to Central Vulnerability","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.20944/preprints202610.0520.v1","summary":"Neurodegenerative diseases (NDs) have traditionally been regarded as brain-centered disorders driven primarily by the accumulation of pathological proteins. However, increasing evidence indicates that systemic metabolic dysfunction, chronic inflammation, intestinal dysbiosis, hepatic abnormalities, and barrier impairment may substantially influence disease susceptibility and progression. This review integrates current evidence on the gut–liver–brain axis (GLBA) and proposes Systemic Metabolic–Immune Reprogramming (SMIR) as a systems-level framework for understanding how peripheral disturbances may be translated…","authors":"Zhou J, Wang J, Li X, Dou J, Chen S, Xue F.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["compute","regenerate"]},{"id":"preprint-10.64898/2026.09.30.755799","kind":"preprint","title":"Intracranial electrophysiology reveals distinct neural representations of nociception and salience in the human brain","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.30.755799","summary":"Neuroimaging studies have shown close overlap between neural representations of nociceptive stimuli and non-nociceptive, salient stimuli (such as low-probability sounds), leading to the proposal that nociception and salience share a common neural substrate in the human brain. Here we use high-resolution intracranial recordings from 13 neurosurgical patients (2,018 total electrodes) to show that neural representations of nociception and salience are anatomically and functionally distinct in the human brain. 77% of 107 electrodes that encoded nociceptive stimuli did not encode low-probability sounds (“nociceptive…","authors":"Joshi S, Polat M, Pantis S, Garg R, Ahmed S, Huang Y, McGeoch PD, Keller CJ, Buch VP, Mackey S, Parvizi J, Ramayya AG.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.07.756069","kind":"preprint","title":"Vibrotactile transcutaneous auricular vagus nerve stimulation (taVNS) during working memory: convergent electrophysiological evidence for cortical efficiency","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.07.756069","summary":"Background: Working memory, the cognitive ability to maintain and manipulate a finite amount of information, is fundamental in reasoning, learning, and decision-making. Working memory erodes in conditions from Alzheimer's disease to stroke to healthy aging. Transcutaneous auricular vagus nerve stimulation (taVNS) is a promising neuromodulation method for improving working memory. By stimulating the auricular branch of the vagus nerve, taVNS is thought to engage ascending arousal systems such as the locus coeruleus-norepinephrine (LC-NE) system. However, the physiological link between LC-NE system modulation via…","authors":"Tan G, Demarest P, Kardashina T, Adams J, Willie JT, Roland J, Gorlewicz JL, Brunner P, Leuthardt EC.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.64898/2026.10.01.751407","kind":"preprint","title":"Accurate Hippocampal Electric Field Modeling for Electroconvulsive Therapy: Numerical Accuracy and Convergence","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.01.751407","summary":"Accurate hippocampal electric field (E-field) prediction is important for individualized electroconvulsive therapy (ECT) dosing and emerging deep-brain stimulation approaches such as temporal interference. Because hippocampal fields are far weaker than those beneath the stimulation electrodes, they are highly sensitive to tissue interfaces, conductivity contrasts, and numerical discretization, so numerical error can rival the physical uncertainties of anatomy and conductivity. We investigate this numerical component of hippocampal dosimetry using individualized head models from eleven ECT patients. Identical hea…","authors":"Noetscher GM, Drumm DA, Neufeld E, Cassara A, Lloyd B, Abbott CC, Deng Z, Makaroff SN.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.01.755613","kind":"preprint","title":"Phase-targeted Poisson closed-loop peripheral nerve stimulation modulates sensorimotor oscillations in human MEG","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.01.755613","summary":"Closed-loop brain stimulation offers a promising approach for modulating neural oscillations, but the mechanisms of phase-dependent neuromodulation remain poorly understood. We developed a real-time MEG-based closed-loop system delivering median nerve stimulation using a phase-modulated Poisson process. Sixteen healthy participants (11 female, 5 male) underwent open-loop characterization followed by closed-loop testing of eight phase-offset conditions (0 degrees-315 degrees), each paired with a statistically matched replay control. Closed-loop stimulation induced robust phase-dependent modulation (14.21 +/- 8.24…","authors":"Baker SN, Zaaimi B.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.64898/2026.10.01.755922","kind":"preprint","title":"Volitional control of a recurrent brain computer interface via covert reinforcement of endogenous reward networks","date":"2026-10-08","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.01.755922","summary":"Recurrent brain-computer interfaces (rBCIs) deliver targeted stimulation to one brain region based on neural activity recorded and processed in real-time at another. In a volitionally controlled rBCI, the user must also learn to intentionally produce the triggering neural activity, a process typically facilitated by an external reward. However, reliance on an external reward introduces a delay between the triggering event and reinforcement that can slow association between the two and, ultimately, control of the rBCI (particularly for neural activity not directly related to an observable behavior such as a goal-…","authors":"McPherson JG, Miller RR, Fetz EE, Perlmutter SI.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate","restore"]},{"id":"preprint-10.64898/2026.10.05.26364594","kind":"preprint","title":"Kilohertz Transcranial Magnetic Perturbation (kTMP) for Upper Extremity Motor Recovery After Stroke: A Nonrandomized Pilot Trial","date":"2026-10-07","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.05.26364594","summary":"Structured Abstract Importance Upper extremity impairment is a leading cause of post-stroke disability, yet clinically approved neuromodulation therapies are currently limited by the risks and costs of surgical implantation. There is an unmet need for non-invasive brain stimulation. Objective To evaluate the feasibility, safety, and preliminary clinical efficacy of a novel form of non-invasive brain stimulation, kilohertz transcranial magnetic perturbation (kTMP), for upper limb motor recovery after stroke. Design A single-center, open-label trial was conducted between September 2025 and April 2026 and comprised…","authors":"Merrick CM, Dai F, Singh S, O’Kidhain I, Reber P, Luu C, Peterchev AV, Sheltraw D, Ivry RB, Labruna L, Ganguly K.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.05.26364665","kind":"preprint","title":"Spatial Neurophysiological Gradients at High Resolution Differentiate Tumor Types in the Human Cortex at the Tumor-Brain Interface","date":"2026-10-07","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.05.26364665","summary":"Brain tumors interact with adjacent neural circuits, with tumor infiltration altering neural physiology, and aberrant neuronal activity, in-turn, promoting tumor growth. Due to limited patient numbers, variable recording methods, and tumor heterogeneity, direct evidence of electrophysiologic distinctions between specific tumor types and these interactions in the intact human brain is lacking. Here, we analyzed intraoperative recordings from 100 participants undergoing tumor resection, epilepsy surgery, or movement disorder deep brain stimulator implant surgeries using clinical electrocorticography (ECoG), mesosc…","authors":"Nelson T, Hsueh B, Hadar P, Das I, Coughlin BF, Mandal A, Wilson T, Peng E, Perley AS, Rabbani H, Ciordia R, Zou J, Bush A, Vissani M, Ghaith H, Cahill J, Yang JC, Munoz W, Torio EF, Glaser AC, Bernstock JD, Collins KL, Cleary DR, Tiwana H…","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.64898/2026.09.30.755810","kind":"preprint","title":"Stimulating a NTS to LC circuit elicits anxiety-like behavior and state-dependent autonomic output.","date":"2026-10-07","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.09.30.755810","summary":"Understanding how the brain integrates internal bodily signals to shape behavior is essential for characterizing the neural basis of interoception. Here, we investigate whether the nucleus of the solitary tract (NTS), a brainstem hub for viscerosensory input, communicates with the locus coeruleus (LC), a noradrenergic nucleus involved in arousal and cognition, to influence anxiety-like behavior. We utilized viral-induced optogenetics combined with electrocardiography and diaphragmatic electromyography to monitor heart rate and respiratory frequency. Prior to behavioral testing we photoactivated transduced NTS ne…","authors":"Butler AG, Bassi JK, Connelly Aa, Melo MRG, Allen AM, McDougall SJ.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.05.26364767","kind":"preprint","title":"Clinical, epidemiological, and economic profile of patients with Parkinson disease eligible for neuromodulation","date":"2026-10-07","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.05.26364767","summary":"Background: Parkinson's disease is a progressive neurodegenerative condition, often associated with motor complications, neuropsychiatric symptoms, and increased care costs in advanced stages. Neuromodulation, especially deep brain stimulation, represents a therapeutic alternative for selected patients. Objective: To characterize the clinical, epidemiological, therapeutic, and economic profile of patients with Parkinson's disease followed at a tertiary center and to estimate the proportion of individuals eligible for neuromodulation. Methods: A cross-sectional descriptive study included 4,060 patients with idiop…","authors":"Glinski TA, da Silva LCK, da Luz JLRN, Rosa TG.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"paper-pmc-pmc13635885","kind":"paper","title":"Ultrasound neuromodulation in brain disorders: from mechanotransduction mechanisms to clinical translation","date":"2026-10-06","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://europepmc.org/article/PMC/PMC13635885","summary":"Europe PMC does not provide an abstract for this record.","authors":"Zhang R, Li L, Tang J, Hu S, Zhang Q, Tan J.","venue":"Frontiers in neuroscience","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.10.05.756028","kind":"preprint","title":"In situ identification of pre-hematopoietic stem cells and their niche","date":"2026-10-06","observedAt":"2026-10-12","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.10.05.756028","summary":"Definitive hematopoietic stem cells (HSCs) emerge predominantly along the ventral surface of the dorsal aorta in the embryonic aorta-gonad-mesonephros (AGM) region, yet the spatial organization of the niche underlying this developmental asymmetry remains poorly understood. Defining the native niche of pre-HSCs has also been hindered by their rarity, transient nature and lack of a single definitive marker for their identification in situ . Here, we integrated single-cell and spatial transcriptomics to construct a spatiotemporal atlas of the niche in the AGM. Neural cells and chondrogenic mesenchyme predominated d…","authors":"Mao X, Zhang N, Bennett L, He X, Scott A, Hall K, Petentler K, Malloy S, Huang S, Kroesen A, McKinney S, Ploumakis A, Yang Z, Dong R, Javier J, Haug J, Li H, Yu Z, Perera A, Vlachos I, Chen F, Trainor P, Speck NA, Li L.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"paper-10.1080/09205063.2026.2741654","kind":"paper","title":"A LIFU-responsive phase-change nanoplatform enhances hippocampal galantamine exposure and cognitive outcomes in APP/PS1 mice.","date":"2026-10-04","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1080/09205063.2026.2741654","summary":"Alzheimer's disease (AD) lacks spatiotemporally controllable strategies for drug delivery to deep brain targets. Galantamine (GTM) is clinically used for symptomatic management of AD, yet systemic dosing is constrained by peripheral adverse effects and limited, nonselective brain exposure. Here, we engineered a PEGylated phase-change liposomal nanoplatform co-loading GTM and perfluoropentane (PFP) (PEG-LIP@PFP@GTM) to integrate noninvasive nose-to-brain delivery with low-intensity focused ultrasound (LIFU)-assisted enhancement of GTM exposure in the hippocampal region. PEG-LIP@PFP@GTM showed a hydrodynamic diame…","authors":"Chen Y, Liu Y, Xie J, Wang S, Zhou D, Song G, Dou Y.","venue":"Journal of biomaterials science. Polymer edition","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.brs.2026.103229","kind":"paper","title":"Subharmonic entrainment of thalamic gamma during deep brain stimulation for multiple sclerosis tremor.","date":"2026-10-03","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.brs.2026.103229","summary":"Europe PMC does not provide an abstract for this record.","authors":"Sarangmat N, Rodriguez-Plazas F, He S, Abdi-Sargezeh B, Liu T, Denison T, Tan H, Robinson R, Bacchini L, Petric B, Fletcher C, Squire L, Arun T, Bogdanovic M, Fitzgerald JJ, Green AL, Oswal A.","venue":"Brain stimulation","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1016/j.neuroimage.2026.122274","kind":"paper","title":"HD-tACS at 40 Hz Improves Consciousness and Brain Connectivity in Prolonged Disorders of Consciousness: A Randomized Sham-Controlled Clinical Trial.","date":"2026-10-03","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.neuroimage.2026.122274","summary":"Background Frequency-specific high-definition transcranial alternating current stimulation (HD-tACS) may facilitate recovery in patients with prolonged disorders of consciousness (pDoC), but predictive biomarkers and mechanistic insights are limited. Objective To investigate the therapeutic efficacy of 40 Hz or 4 Hz HD-tACS in pDoC. Methods Sixty pDoC patients were randomized into four groups receiving 40 Hz or 4 Hz HD-tACS, each with a corresponding sham condition. Behavioral recovery was assessed via Coma Recovery Scale-Revised (CRS-R), network connectivity was analyzed with electroencephalography (EEG), and b…","authors":"Hu J, Mou C, Jiang X, Zhang L, Ling Y, Zhao J, Meng F, He F, Wang H, Peng F, Ning J, Gao J, Xu C, Xiao J, Zhao S, Yu J, Pan G, Luo B.","venue":"NeuroImage","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.neuroimage.2026.122273","kind":"paper","title":"40 Hz Transcutaneous Auricular Vagus Nerve Stimulation Enhances Verbal Free Recall in Healthy Adults by Modulating Frontal Theta Oscillations.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.neuroimage.2026.122273","summary":"Background Transcutaneous auricular vagus nerve stimulation (taVNS) is a non-invasive neuromodulation approach that may influence memory-related brain activity. Theta oscillations are closely related to episodic memory processing, but it remains unclear whether taVNS modulates memory-related theta activity in a frequency-specific manner and how these effects change after stimulation. Objective This study investigated the sustained effects of 20 Hz and 40 Hz taVNS on free recall and resting-state EEG theta oscillations in healthy young adults. Methods Forty-four participants were enrolled in this randomized, sing…","authors":"Luo Y, Yin S, Chen L, Gao H, Zhao P, Wen H.","venue":"NeuroImage","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.neuroimage.2026.122271","kind":"paper","title":"The impact of behavioural activity on the EEG power spectrum, its source localisation, and global functional connectivity in rats Behavioural modulation of rat EEG dynamics.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.neuroimage.2026.122271","summary":"The behavioural activity of freely moving animals is a confounding factor that affects the recording, analysis, and final results of animal EEG experiments. Along with the lack of standardisation in animal in vivo electrophysiology experiments, this could lead to huge inconsistencies, especially in the analysis of centrally acting drugs. Therefore, the main aim of this paper is to investigate the effects of behavioural activity versus inactivity on the multichannel EEG in freely moving rats. In a large sample (n = 116) of waking recordings from 12 cortical electrodes (ECoG) in Wistar rats, we evaluated behaviour…","authors":"Vejmola Č, Jiříček S, Bochin M, Koudelka V, Páleníček T.","venue":"NeuroImage","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"paper-10.1016/j.actbio.2026.10.003","kind":"paper","title":"BaTiO 3 -based Piezoelectric Wireless Neuromodulation: From Molecular Mechanisms to Clinical Translation Challenges.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.actbio.2026.10.003","summary":"Neurological injuries remain difficult to treat due to the complex microenvironment and the limited intrinsic regenerative capacity of neural tissues. Recently, wireless neuromodulation based on piezoelectric nanomaterials, particularly barium titanate (BaTiO 3 ), has emerged as a promising alternative to conventional implantable electrical stimulation. Polar BaTiO 3 ceramics generally have higher piezoelectric charge coefficients than conventional Polyvinylidene Fluoride (PVDF) and Poly(vinylidene fluoride-co-trifluoroethylene) (P(VDF-TrFE)) films, are more resistant to degradation than ZnO, and are lead-free u…","authors":"Xu X, Wu T, Huang Y, Sun T, Li Y, Cao W, Xue C, Zhang M.","venue":"Acta biomaterialia","status":"Peer-reviewed / indexed","topics":["stimulate","restore","regenerate"]},{"id":"paper-10.3171/2026.4.jns26203","kind":"paper","title":"Cryoprobe to current practice: neurosurgical legacies of Dr. Irving S. Cooper in movement disorders.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.3171/2026.4.jns26203","summary":"Before the advent of levodopa therapy for Parkinson's disease, surgical lesioning of the motor thalamus or globus pallidus represented the primary therapeutic intervention for Parkinson's disease and essential tremor at a time when effective medical alternatives were severely limited. In this context, Irving S. Cooper directed one of the most prolific and controversial lesioning practices of the mid-20th century, performing thousands of procedures and documenting outcomes. Through chemopallidectomy, chemothalamectomy, and later cryosurgical techniques, Cooper investigated the relationship between basal ganglia t…","authors":"Fisher K, Tsirelman K, Baweja SS, Jain AK, Fekete R.","venue":"Journal of neurosurgery","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1126/sciadv.aee1540","kind":"paper","title":"Highly stretchable, hair-compatible multichannel neural interface with time-stable hydrogel for high-fidelity long-term EEG sensing.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1126/sciadv.aee1540","summary":"Reliable brain-computer interfaces (BCIs) require electroencephalography (EEG) sensors that maintain conformal, low-impedance contact through hair, motion, and repeated use. Here, we present MindStretcH, a stretchable and hair-compatible EEG platform integrating a kirigami-patterned elastomeric mesh, deformable eutectic gallium-indium (EGaIn) interconnects, and detachable hydrogel-based conical electrodes. The system adapts to variations in head geometry, preserves electrical performance under substantial mechanical deformation, and maintains stable electrode-scalp contact over prolonged use. Longitudinal motor-…","authors":"Hsieh JC, Yao M, Alawieh H, Koptelova V, Kumar S, Tang KWK, Wang W, Jeong J, Ding H, Ahmad Z, Wang D, Engrav T, Wang R, Gupta A, He W, Moscoso-Barrera WD, Grimes A, Millán JDR, Wang H.","venue":"Science advances","status":"Peer-reviewed / indexed","topics":["record","restore"]},{"id":"paper-10.1109/tmi.2026.3739833","kind":"paper","title":"EM-SliceCrafter: Distilling Lightweight 2D CNNs for Efficient 3D EM Neuron Segmentation.","date":"2026-10-02","observedAt":"2026-10-12","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1109/tmi.2026.3739833","summary":"Accurate 3D neuron segmentation from large-scale electron microscopy (EM) volumes is a cornerstone of connectomics, yet it is hampered by a trade-off between accuracy and computational efficiency. While 3D Convolutional Neural Networks (CNNs) offer high accuracy by predicting 3D affinity maps, their high computational cost and limited input size impede their application to large-scale data. To overcome this, we introduce EM-SliceCrafter, a novel framework that employs a lightweight 2D CNN for both efficient and precise 3D neuron segmentation. Our method generates a 3D affinity map by computing distances between…","authors":"Shi H, Liu X, Chen Y, Cai M, Chen X, Xiong Z.","venue":"IEEE transactions on medical imaging","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"news-nibib-0-nih-demystifies-vital-biomedical-tech-congressional-staff","kind":"news","title":"NIH Demystifies Vital Biomedical Tech for Congressional Staff","date":"2025-08-15","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/nih-demystifies-vital-biomedical-tech-congressional-staff","summary":"Biomedical engineers and imaging researchers gave 45 congressional staff a glimpse of transformative medical technologies on the horizon, underscoring the crucial role of medical tools in human health. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-1-innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","kind":"news","title":"Innovative imaging tool could improve diagnosis and treatment of hearing loss","date":"2025-08-04","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","summary":"Researchers from the Keck School of Medicine of USC with NIH funding including NIBIB have adapted a low-cost imaging method developed for ophthalmology and used it to visualize tiny structures in the human inner ear. &nbsp; Source: USC Keck School of Medicine News. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-2-scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","kind":"news","title":"Scientists Develop High-Performance MRI Scanner in Effort to Define Microscopic Brain Structures","date":"2025-07-16","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","summary":"A scientific team supported in part by NIH has developed a new, ultra-high-resolution brain imaging system that can reconstruct microscopic brain structures that are disrupted in neurological and neuropsychiatric brain disorders. The new system is a significant advance over conventional magnetic resonance imaging (MRI) scanners that cannot visualize these tiny but clinically important structures. Source: NIH More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-3-high-tech-sticker-can-identify-real-human-emotions","kind":"news","title":"High-tech sticker can identify real human emotions","date":"2025-04-22","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/high-tech-sticker-can-identify-real-human-emotions","summary":"Saying one thing while feeling another is part of being human, but bottling up emotions can have serious psychological consequences like anxiety or panic attacks. To help health care providers tell the difference, a team led by scientists at Penn State has created a stretchable, rechargeable sticker that can detect real emotions — by measuring things like skin temperature and heart rate — even when users put on a brave face. &nbsp;The researchers recently unveiled the wearable patch that can simultaneously and accurately track multiple emotional signals in a study published in the journal Nano Letters. Read more…","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-4-your-skin-breathing-new-wearable-device-can-measure-it","kind":"news","title":"Your skin is breathing. This new wearable device can measure it.","date":"2025-04-10","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/your-skin-breathing-new-wearable-device-can-measure-it","summary":"Northwestern University researchers have developed the first wearable device for measuring gases emitted from and absorbed by the skin. By analyzing these gases, the device offers an entirely new way to assess skin health, including monitoring wounds, detecting skin infections, tracking hydration levels, quantifying exposure to harmful environmental chemicals and more. Source: Northwestern Now More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-5-ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","kind":"news","title":"AI tool can track effectiveness of multiple sclerosis treatments","date":"2025-04-08","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","summary":"A new artificial intelligence (AI) tool that can help interpret and assess how well treatments are working for patients with multiple sclerosis (MS) has been developed by University College London researchers. Source: University College London News More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["compute"]},{"id":"news-nibib-6-revealing-capillaries-cells-living-organs-ultrasound","kind":"news","title":"Revealing capillaries and cells in living organs with ultrasound","date":"2025-04-04","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/revealing-capillaries-cells-living-organs-ultrasound","summary":"While medical centers use ultrasound daily, so far this technology has not been capable of observing body tissues at the scale of cells. Physicists at several universities including CalTech have now developed a microscopy technique based on ultrasound to reveal capillaries and cells across living organs -- something that wasn't possible before. Source: Delft University of Technology More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]},{"id":"news-nibib-7-decreasing-invasiveness-deep-brain-stimulation","kind":"news","title":"Decreasing the invasiveness of deep brain stimulation","date":"2025-03-20","observedAt":"2026-10-12","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/decreasing-invasiveness-deep-brain-stimulation","summary":"Researchers are developing a preclinical method to stimulate the brain without drilling into the skull by guiding a catheter through the cerebrospinal fluid. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]}]};
